-- 0201: aṣl from every book, batch 19 — each book's own statement (read by its profile; Lane in English), verbatim
-- with block + page and a plain English line; primary = the meaning most books share. Quotes checked against blocks.
-- aslmb_19: aṣl per book for 25 roots that rested on Ibn Fāris alone (AGR:VOC:002/017).
-- Each row: the book's own words as printed + block + page + entry. ONE primary per root, by the reading most books share
-- (tie -> the earliest book). Standalone: INSERT OR IGNORE + guarded UPDATEs; safe to re-run. No row deleted.
-- علو
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:khalil_kitab_ayn', 'علو', '451e091a790914d6a5d018b6f3', 'ومنه العَلاءُ والعُلُوّ، فالعَلاءُ الرِّفْعَةُ، والعُلُوُّ العظمة والتجبّر', 'rank is height; rising is greatness and pride', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', '598', NULL, 'blk_kay_seg_77c653907aecb73e', 0, NULL, 'Marker: head gloss. Reading: height, greatness.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:ibn_durayd_jamharat_lugha', 'علو', '451e091a790914d6a5d018b6f3', 'العُلْو: ضد السُّفل', 'the top: opposite of the bottom', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_0b75f57c1d24fdd0', 0, NULL, 'Marker: head gloss. Reading: top. Primary: height — 10 of 10 books (al-Khalīl blk_kay_seg_77c653907aecb73e; Ibn Durayd blk_jam_0b75f57c1d24fdd0; al-Jawharī blk_sih_98407d32c0b2fecb; Ibn Fāris blk_mqy_401a6998646350ad; al-Rāghib blk_mfr_2100f1e056b35d91; Lisān blk_lsn_8d3147d1317c69cc; al-Miṣbāḥ blk_msb_67d178e4c538c247; al-Qāmūs blk_qms_ad825375eadf14dd; Tāj blk_taj_4156b51e80b65284; Lane blk_lane_4d79ab2c6abeb2fe).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:jawhari_sihah', 'علو', '451e091a790914d6a5d018b6f3', 'عَلا في المكان يَعْلو عُلوًّا. وعَلِيَ في الشرف بالكسر يَعْلى عَلا', 'rose high in place; was high in rank', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_899dacc0e3bb3889', '4828', 6, 'blk_sih_98407d32c0b2fecb', 0, NULL, 'Marker: head gloss. Reading: rising high.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:raghib_mufradat', 'علو', '451e091a790914d6a5d018b6f3', 'العُلْوُ: ضدّ السُّفْل، والعُلْوِيُّ والسُّفْليُّ المنسوب إليهما، والعُلُوُّ: الارتفاعُ', 'the top, opposite of bottom; rising', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_296c837ae148f1c9', '582', 1, 'blk_mfr_2100f1e056b35d91', 0, NULL, 'Marker: head gloss. Reading: top, rising.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:ibn_manzur_lisan_arab', 'علو', '451e091a790914d6a5d018b6f3', 'عُلْو كُلِّ شَيْءٍ وعِلْوه وعَلْوُه وعُلاوَتُه وعَالِيه وعالِيَتُه: أَرْفَعُه', 'the top of anything: its highest part', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_6602586bf3c8bce7', '1334', 2, 'blk_lsn_8d3147d1317c69cc', 0, NULL, 'Marker: head gloss. Reading: highest part.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:fayyumi_misbah_munir', 'علو', '451e091a790914d6a5d018b6f3', 'عُلْوُ الدَّارِ وَغَيْرِهَا خِلَافُ السُّفْلِ', 'the upper part of a house, not the lower', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_b351687f2866005b', '2108', NULL, 'blk_msb_67d178e4c538c247', 0, NULL, 'Marker: head gloss. Reading: upper part.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:qamus_muhit', 'علو', '451e091a790914d6a5d018b6f3', 'عُلْوُ الشيءِ، مثلثةً، وعُلاوَتُه، بالضم، وعالِيَتُه: أَرْفَعُه', 'the top of a thing: its highest part', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_e726a56cf65adb18', NULL, NULL, 'blk_qms_ad825375eadf14dd', 0, NULL, 'Marker: Qāmūs gloss. Reading: highest part.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:zabidi_taj_arus', 'علو', '451e091a790914d6a5d018b6f3', 'عُلْوُ الشَّيءَ، مُثَلَّثَةً، ﴿وعُلاوَتُه، بالضَّمِّ، وعالِيَتُه: أَرْفَعُه', 'the top of a thing: its highest part', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_b266d3bf4ab82706', '82', 39, 'blk_taj_4156b51e80b65284', 0, NULL, 'Marker: Qāmūs gloss. Reading: highest part.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:علو:lane_lexicon', 'علو', '451e091a790914d6a5d018b6f3', 'It (a thing, Mṣb) was, or became, high, elevated, or lofty', 'it was or became high', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_0ff16677368f578c', '2142', NULL, 'blk_lane_4d79ab2c6abeb2fe', 0, NULL, 'Marker: first sense A1. Reading: being high.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: height.', updated_at = datetime('now') WHERE id = 'ASL:علو:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
