INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عند:raghib_mufradat', 'عند', '4cde950b17fc2979dceccedc3c', 'عند: لفظ موضوع للقرب، فتارة يستعمل في المكان، وتارة في الاعتقاد', 'a word for nearness, in place or belief', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_76c3053690559ca8', '590', 1, 'blk_mfr_8d6c2af1e64ea1ae', 0, NULL, 'Marker: head gloss. Reading: nearness. Differs from the main reading (turning off the right way).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عند:ibn_manzur_lisan_arab', 'عند', '4cde950b17fc2979dceccedc3c', 'عَنَدَ الرجلُ يَعْنُد عَنْداً وعُنُوداً وعَنَداً: عَتَا وطَغَا وجاوزَ قَدْرَه', 'was proud, went too far, overstepped his limit', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_8239e5deb753c699', '1749', 3, 'blk_lsn_d357495bfb73a7d5', 0, NULL, 'Marker: head gloss. Reading: overstepping.', 'high', 'active');
