INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عند:zabidi_taj_arus', 'عند', '4cde950b17fc2979dceccedc3c', 'وعَنَداً، محرَّكةً: تَبَاعَدَ و (مالَ) وعَدَلَ انحرَفَ إِلى عَنَدٍ أَي جانِبٍ', 'moved away, turned aside to one side', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_1bc3d5be09275d78', '423', 8, 'blk_taj_e1a87ece00449fb6', 0, NULL, 'Marker: Qāmūs gloss + additions. Reading: turning aside. Filed under عنجرد in this book.', 'high', 'active');
