INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:غنم:khalil_kitab_ayn', 'غنم', '16760c754d9657d92e41980bf7', 'هذه غَنَمٌ لفظٌ للجَماعةِ، فإذا أفردْت قُلْتَ: شاةٌ', 'ghanam: a word for the flock; one is shāt', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_e42d7755302b1fc2', '1534', NULL, 'blk_kay_68123ca962fc2f34', 0, NULL, 'Marker: head gloss. Reading: sheep flock. Primary: sheep — 6 of 10 books (al-Khalīl blk_kay_68123ca962fc2f34; Ibn Durayd blk_jam_b33917b5579144fe; al-Jawharī blk_sih_6fd75edce4b2eab3; Lisān blk_lsn_1b6c7eb83f90fc02; al-Qāmūs blk_qms_a375c732791912af; Tāj blk_taj_fa3577daef3d3241). Other readings: gaining, spoil: Ibn Fāris, al-Rāghib, al-Miṣbāḥ, Lane.', 'high', 'active');
